package com.unicare.dispensary.screening;import java.time.LocalDate;import java.time.LocalDateTime;public record ScreeningResponse(Long id,Long studentId,String studentName,String studentNumber,LocalDate date,String allergies,String conditions,String currentMedication,String wellbeing,String symptoms,String notes,LocalDateTime updatedAt){static ScreeningResponse from(HealthScreening s){return new ScreeningResponse(s.getId(),s.getStudent().getId(),s.getStudent().getFullName(),s.getStudent().getStudentNumber(),s.getScreeningDate(),s.getAllergies(),s.getConditions(),s.getCurrentMedication(),s.getWellbeing(),s.getSymptoms(),s.getNotes(),s.getCreatedAt());}}
